import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdirSync, writeFileSync, rmSync, existsSync } from 'fs';
import { join } from 'path';
import { housekeep } from './housekeeping.js';

const TEST_DIR = '/tmp/eval-framework-housekeeping-test';

function createResult(
  dir: string,
  opts: { summary?: boolean; transcript?: boolean; passedRuns?: number }
) {
  mkdirSync(dir, { recursive: true });
  if (opts.summary !== false) {
    writeFileSync(
      join(dir, 'summary.json'),
      JSON.stringify({
        totalRuns: 2,
        passedRuns: opts.passedRuns ?? 1,
        passRate: '50%',
        meanDuration: 10,
      })
    );
  }
  if (opts.transcript !== false) {
    const runDir = join(dir, 'run-1');
    mkdirSync(runDir, { recursive: true });
    writeFileSync(join(runDir, 'result.json'), JSON.stringify({ status: 'passed', duration: 10 }));
    writeFileSync(join(runDir, 'transcript-raw.jsonl'), '{"role":"assistant"}\n');
  }
}

describe('housekeep', () => {
  beforeEach(() => {
    mkdirSync(TEST_DIR, { recursive: true });
    // Enable classifier for tests that expect non-model failures to be cleaned up
    process.env.AI_GATEWAY_API_KEY = 'test-key';
  });

  afterEach(() => {
    if (existsSync(TEST_DIR)) {
      rmSync(TEST_DIR, { recursive: true });
    }
    // Clean up env var
    delete process.env.AI_GATEWAY_API_KEY;
  });

  it('keeps newest result and removes older duplicate', () => {
    // Newer timestamp
    createResult(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'), {});
    // Older timestamp
    createResult(join(TEST_DIR, 'exp', '2024-01-25T12-00-00.000Z', 'eval-1'), {});

    const stats = housekeep(TEST_DIR, 'exp');

    expect(stats.removedDuplicates).toBe(1);
    expect(existsSync(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'))).toBe(true);
    expect(existsSync(join(TEST_DIR, 'exp', '2024-01-25T12-00-00.000Z', 'eval-1'))).toBe(false);
  });

  it('removes incomplete results (no summary)', () => {
    createResult(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'), {
      summary: false,
    });

    const stats = housekeep(TEST_DIR, 'exp');

    expect(stats.removedIncomplete).toBe(1);
    expect(existsSync(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'))).toBe(false);
  });

  it('removes empty timestamp directories', () => {
    // Create a result, then mark it as incomplete so it gets removed
    createResult(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'), {
      summary: false,
    });

    const stats = housekeep(TEST_DIR, 'exp');

    expect(stats.removedEmptyDirs).toBe(1);
    expect(existsSync(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z'))).toBe(false);
  });

  it('dry run does not delete anything', () => {
    createResult(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'), {});
    createResult(join(TEST_DIR, 'exp', '2024-01-25T12-00-00.000Z', 'eval-1'), {});

    const stats = housekeep(TEST_DIR, 'exp', { dry: true });

    expect(stats.removedDuplicates).toBe(1);
    // Both should still exist
    expect(existsSync(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'))).toBe(true);
    expect(existsSync(join(TEST_DIR, 'exp', '2024-01-25T12-00-00.000Z', 'eval-1'))).toBe(true);
  });

  it('handles non-existent experiment gracefully', () => {
    const stats = housekeep(TEST_DIR, 'no-such-exp');
    expect(stats.removedDuplicates).toBe(0);
    expect(stats.removedIncomplete).toBe(0);
    expect(stats.removedEmptyDirs).toBe(0);
  });

  it('removes results with infra classification from classification.json', () => {
    const evalDir = join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1');
    createResult(evalDir, { passedRuns: 0 });
    writeFileSync(
      join(evalDir, 'classification.json'),
      JSON.stringify({ failureType: 'infra', failureReason: 'API error' })
    );

    const stats = housekeep(TEST_DIR, 'exp');

    expect(stats.removedNonModelFailures).toBe(1);
    expect(existsSync(evalDir)).toBe(false);
  });

  it('removes results with timeout classification from classification.json', () => {
    const evalDir = join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1');
    createResult(evalDir, { passedRuns: 0 });
    writeFileSync(
      join(evalDir, 'classification.json'),
      JSON.stringify({ failureType: 'timeout', failureReason: 'Hit time limit' })
    );

    const stats = housekeep(TEST_DIR, 'exp');

    expect(stats.removedNonModelFailures).toBe(1);
    expect(existsSync(evalDir)).toBe(false);
  });

  it('keeps results with model classification', () => {
    const evalDir = join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1');
    createResult(evalDir, { passedRuns: 0 });
    writeFileSync(
      join(evalDir, 'classification.json'),
      JSON.stringify({ failureType: 'model', failureReason: 'Incorrect code' })
    );

    const stats = housekeep(TEST_DIR, 'exp');

    expect(stats.removedNonModelFailures).toBe(0);
    expect(existsSync(evalDir)).toBe(true);
  });

  it('keeps results without transcript if summary has totalRuns > 0', () => {
    createResult(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'), {
      transcript: false,
      passedRuns: 0,
    });

    const stats = housekeep(TEST_DIR, 'exp');

    // Should be kept (model failure with valid summary)
    expect(stats.removedIncomplete).toBe(0);
    expect(existsSync(join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1'))).toBe(true);
  });

  it('keeps non-model failures when classifier is disabled', () => {
    const evalDir = join(TEST_DIR, 'exp', '2024-01-26T12-00-00.000Z', 'eval-1');
    createResult(evalDir, { passedRuns: 0 });
    writeFileSync(
      join(evalDir, 'classification.json'),
      JSON.stringify({ failureType: 'infra', failureReason: 'API error' })
    );

    // Disable classifier by removing env var
    delete process.env.AI_GATEWAY_API_KEY;

    const stats = housekeep(TEST_DIR, 'exp');

    // Non-model failures should NOT be removed when classifier is disabled
    expect(stats.removedNonModelFailures).toBe(0);
    expect(existsSync(evalDir)).toBe(true);
  });
});

/**
 * Eval fixture discovery and validation.
 */

import { readFileSync, readdirSync, statSync, existsSync, mkdirSync, copyFileSync } from 'fs';
import { join, resolve, dirname } from 'path';
import type { EvalFixture, ValidationMode } from './types.js';
import { REQUIRED_EVAL_FILES, EXCLUDED_FILES } from './types.js';

export interface FixtureLoadOptions {
  validation?: ValidationMode;
}

/**
 * Error thrown when an eval fixture is invalid.
 */
export class FixtureValidationError extends Error {
  constructor(
    public fixtureName: string,
    message: string
  ) {
    super(`Eval "${fixtureName}": ${message}`);
    this.name = 'FixtureValidationError';
  }
}

/**
 * Check if a file exists with exact case match (case-sensitive even on Mac/Windows).
 * Returns true only if the file exists AND the case matches exactly.
 */
function existsWithExactCase(dirPath: string, fileName: string): boolean {
  try {
    const files = readdirSync(dirPath);
    return files.includes(fileName);
  } catch {
    return false;
  }
}

/**
 * Discovers all eval fixtures in a directory.
 * Recursively searches for directories containing PROMPT.md.
 * Supports nested organization like "vercel-cli/deploy" or "flags/create-flag".
 */
export function discoverFixtures(evalsDir: string): string[] {
  const absolutePath = resolve(evalsDir);

  if (!existsSync(absolutePath)) {
    throw new Error(`Evals directory not found: ${absolutePath}`);
  }

  const fixtures: string[] = [];

  function walk(dir: string, basePath: string = '') {
    const entries = readdirSync(dir);

    for (const entry of entries) {
      // Skip hidden directories and files
      if (entry.startsWith('.')) {
        continue;
      }

      const entryPath = join(dir, entry);

      // Only consider directories
      if (!statSync(entryPath).isDirectory()) {
        continue;
      }

      const relativePath = basePath ? `${basePath}/${entry}` : entry;

      // Check if this directory contains PROMPT.md (potential fixture)
      if (existsWithExactCase(entryPath, 'PROMPT.md')) {
        fixtures.push(relativePath);
      } else {
        // Not a fixture directory, recurse into it
        walk(entryPath, relativePath);
      }
    }
  }

  walk(absolutePath);
  return fixtures.sort();
}

/**
 * Validates that a fixture has all required files with correct case.
 * Returns an array of missing file names, or empty array if valid.
 * Note: Accepts either EVAL.ts or EVAL.tsx for the eval file.
 * Case-sensitive: 'prompt.md' will fail even on Mac/Windows.
 */
export function validateFixtureFiles(
  fixturePath: string,
  options: FixtureLoadOptions = {}
): string[] {
  const missing: string[] = [];
  const validation = options.validation ?? 'vitest';

  for (const file of REQUIRED_EVAL_FILES) {
    // Special case: Accept either EVAL.ts or EVAL.tsx (both case-sensitive)
    if (file === 'EVAL.ts') {
      if (validation === 'none') {
        continue;
      }
      const hasEvalTs = existsWithExactCase(fixturePath, 'EVAL.ts');
      const hasEvalTsx = existsWithExactCase(fixturePath, 'EVAL.tsx');
      if (!hasEvalTs && !hasEvalTsx) {
        missing.push('EVAL.ts or EVAL.tsx');
      }
    } else {
      if (!existsWithExactCase(fixturePath, file)) {
        missing.push(file);
      }
    }
  }

  return missing;
}

/**
 * Validates the package.json of a fixture.
 * Ensures it has "type": "module".
 */
export function validatePackageJson(fixturePath: string): { isModule: boolean; error?: string } {
  const packageJsonPath = join(fixturePath, 'package.json');

  try {
    const content = readFileSync(packageJsonPath, 'utf-8');
    const pkg = JSON.parse(content);

    if (pkg.type !== 'module') {
      return {
        isModule: false,
        error: 'package.json must have "type": "module"',
      };
    }

    return { isModule: true };
  } catch (error) {
    if (error instanceof SyntaxError) {
      return {
        isModule: false,
        error: 'package.json is not valid JSON',
      };
    }
    throw error;
  }
}

/**
 * Loads a single eval fixture with full validation.
 */
export function loadFixture(
  evalsDir: string,
  name: string,
  options: FixtureLoadOptions = {}
): EvalFixture {
  const fixturePath = resolve(evalsDir, name);

  if (!existsSync(fixturePath)) {
    throw new FixtureValidationError(name, `Directory not found: ${fixturePath}`);
  }

  // Validate required files
  const missingFiles = validateFixtureFiles(fixturePath, options);
  if (missingFiles.length > 0) {
    throw new FixtureValidationError(
      name,
      `Missing required files: ${missingFiles.join(', ')}`
    );
  }

  // Validate package.json
  const pkgValidation = validatePackageJson(fixturePath);
  if (pkgValidation.error) {
    throw new FixtureValidationError(name, pkgValidation.error);
  }

  // Read prompt (case-sensitive check)
  if (!existsWithExactCase(fixturePath, 'PROMPT.md')) {
    throw new FixtureValidationError(name, 'PROMPT.md not found (case-sensitive: must be uppercase)');
  }
  const promptPath = join(fixturePath, 'PROMPT.md');
  const prompt = readFileSync(promptPath, 'utf-8');

  return {
    name,
    path: fixturePath,
    prompt,
    isModule: pkgValidation.isModule,
  };
}

/**
 * Discovers and loads all valid eval fixtures from a directory.
 * Returns both valid fixtures and any validation errors encountered.
 */
export function loadAllFixtures(
  evalsDir: string,
  options: FixtureLoadOptions = {}
): {
  fixtures: EvalFixture[];
  errors: FixtureValidationError[];
} {
  const fixtureNames = discoverFixtures(evalsDir);
  const fixtures: EvalFixture[] = [];
  const errors: FixtureValidationError[] = [];

  for (const name of fixtureNames) {
    try {
      const fixture = loadFixture(evalsDir, name, options);
      fixtures.push(fixture);
    } catch (error) {
      if (error instanceof FixtureValidationError) {
        errors.push(error);
      } else {
        throw error;
      }
    }
  }

  return { fixtures, errors };
}

/**
 * Gets a list of all files in a fixture directory.
 * Excludes PROMPT.md, EVAL.ts, node_modules, and .git.
 */
export function getFixtureFiles(
  fixturePath: string,
  excludePatterns: readonly string[] = EXCLUDED_FILES
): string[] {
  const files: string[] = [];

  function walk(dir: string, basePath: string = '') {
    const entries = readdirSync(dir);

    for (const entry of entries) {
      const relativePath = basePath ? `${basePath}/${entry}` : entry;

      // Check if should be excluded
      if (excludePatterns.some((pattern) => relativePath === pattern || entry === pattern)) {
        continue;
      }

      const fullPath = join(dir, entry);
      const stat = statSync(fullPath);

      if (stat.isDirectory()) {
        walk(fullPath, relativePath);
      } else {
        files.push(relativePath);
      }
    }
  }

  walk(fixturePath);
  return files.sort();
}

/**
 * Reads all fixture files into a map.
 * Keys are relative paths, values are raw file contents (never decoded, so
 * binary fixture assets survive the round trip).
 */
export function readFixtureFiles(
  fixturePath: string,
  excludePatterns?: readonly string[]
): Map<string, Buffer> {
  const files = getFixtureFiles(fixturePath, excludePatterns);
  const contents = new Map<string, Buffer>();

  for (const file of files) {
    const fullPath = join(fixturePath, file);
    contents.set(file, readFileSync(fullPath));
  }

  return contents;
}

/**
 * Copies all fixture files into `destPath`, preserving relative layout.
 *
 * Prefer this over `readFixtureFiles` + `writeFileSync` when the destination is
 * the filesystem: the bytes never enter the heap, so there is no encoding to get
 * wrong and no need to hold an entire fixture tree in memory at once.
 */
export function copyFixtureFiles(
  fixturePath: string,
  destPath: string,
  excludePatterns?: readonly string[]
): void {
  for (const file of getFixtureFiles(fixturePath, excludePatterns)) {
    const fullPath = join(destPath, file);
    mkdirSync(dirname(fullPath), { recursive: true });
    copyFileSync(join(fixturePath, file), fullPath);
  }
}

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { isNonModelFailure } from './classifier.js';
import { mkdtempSync, writeFileSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';

describe('isNonModelFailure', () => {
  let tempDir: string;

  beforeEach(() => {
    tempDir = mkdtempSync(join(tmpdir(), 'classifier-test-'));
  });

  afterEach(() => {
    rmSync(tempDir, { recursive: true });
  });

  it('returns true for infra failure', () => {
    writeFileSync(
      join(tempDir, 'classification.json'),
      JSON.stringify({ failureType: 'infra', failureReason: 'Rate limited' })
    );
    expect(isNonModelFailure(tempDir)).toBe(true);
  });

  it('returns true for timeout failure', () => {
    writeFileSync(
      join(tempDir, 'classification.json'),
      JSON.stringify({ failureType: 'timeout', failureReason: 'Timed out' })
    );
    expect(isNonModelFailure(tempDir)).toBe(true);
  });

  it('returns false for model failure', () => {
    writeFileSync(
      join(tempDir, 'classification.json'),
      JSON.stringify({ failureType: 'model', failureReason: 'Wrong code' })
    );
    expect(isNonModelFailure(tempDir)).toBe(false);
  });

  it('returns false for acknowledged infra failure', () => {
    writeFileSync(
      join(tempDir, 'classification.json'),
      JSON.stringify({ failureType: 'infra', failureReason: 'Rate limited', acknowledged: true })
    );
    expect(isNonModelFailure(tempDir)).toBe(false);
  });

  it('returns false for acknowledged timeout failure', () => {
    writeFileSync(
      join(tempDir, 'classification.json'),
      JSON.stringify({ failureType: 'timeout', failureReason: 'Timed out', acknowledged: true })
    );
    expect(isNonModelFailure(tempDir)).toBe(false);
  });

  it('returns false when no classification.json exists', () => {
    expect(isNonModelFailure(tempDir)).toBe(false);
  });
});

/**
 * Integration tests for Docker sandbox.
 * These tests require Docker to be running.
 * Skip with: SKIP_DOCKER_TESTS=1 npm test
 */

import { describe, it, expect, beforeAll } from 'vitest';
import { DockerSandboxManager } from './docker-sandbox.js';
import type { CommandResult } from './sandbox.js';

/**
 * A real 1x1 PNG. Byte 0 is 0x89, which is not a valid UTF-8 lead byte, so any
 * UTF-8 decode of this file replaces it with U+FFFD.
 */
const PNG_BYTES = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64'
);

// Check if Docker is available
async function isDockerAvailable(): Promise<boolean> {
  try {
    const { execSync } = await import('child_process');
    execSync('docker info', { stdio: 'ignore' });
    return true;
  } catch {
    return false;
  }
}

describe('DockerSandboxManager', () => {
  const skipDocker = process.env.SKIP_DOCKER_TESTS === '1';
  let dockerAvailable = false;

  beforeAll(async () => {
    if (!skipDocker) {
      dockerAvailable = await isDockerAvailable();
    }
  });

  describe('when Docker is available', () => {
    it('can create and stop a sandbox', async () => {
      if (skipDocker || !dockerAvailable) {
        console.log('Skipping: Docker not available');
        return;
      }

      const sandbox = await DockerSandboxManager.create({
        timeout: 60000,
        runtime: 'node24',
      });

      expect(sandbox.sandboxId).toBeTruthy();
      expect(sandbox.getWorkingDirectory()).toBe('/home/sandbox/workspace');

      await sandbox.stop();
    }, 120000); // 2 minute timeout for image pull

    it('can run commands', async () => {
      if (skipDocker || !dockerAvailable) {
        console.log('Skipping: Docker not available');
        return;
      }

      const sandbox = await DockerSandboxManager.create({
        timeout: 60000,
        runtime: 'node24',
      });

      try {
        const result = await sandbox.runCommand('echo', ['hello world']);
        expect(result.exitCode).toBe(0);
        expect(result.stdout.trim()).toBe('hello world');
      } finally {
        await sandbox.stop();
      }
    }, 120000);

    it('can write and read files', async () => {
      if (skipDocker || !dockerAvailable) {
        console.log('Skipping: Docker not available');
        return;
      }

      const sandbox = await DockerSandboxManager.create({
        timeout: 60000,
        runtime: 'node24',
      });

      try {
        await sandbox.writeFiles({
          'test.txt': 'Hello from test!',
          'nested/file.json': '{"key": "value"}',
        });

        const content1 = await sandbox.readFile('test.txt');
        expect(content1.trim()).toBe('Hello from test!');

        const content2 = await sandbox.readFile('nested/file.json');
        expect(JSON.parse(content2)).toEqual({ key: 'value' });
      } finally {
        await sandbox.stop();
      }
    }, 120000);

    it('reads binary files back byte-for-byte', async () => {
      if (skipDocker || !dockerAvailable) {
        console.log('Skipping: Docker not available');
        return;
      }

      const sandbox = await DockerSandboxManager.create({
        timeout: 60000,
        runtime: 'node24',
      });

      try {
        await sandbox.uploadFiles([{ path: 'favicon.png', content: PNG_BYTES }]);

        // Proves `base64` exists in the image and that the transport survives
        // bytes the UTF-8 path would replace with U+FFFD.
        const bytes = await sandbox.readFileBuffer('favicon.png');
        expect(Buffer.compare(bytes, PNG_BYTES)).toBe(0);

        const asText = await sandbox.readFile('favicon.png');
        expect(Buffer.from(asText, 'utf-8')).not.toEqual(PNG_BYTES);
      } finally {
        await sandbox.stop();
      }
    }, 120000);

    it('can run npm commands', async () => {
      if (skipDocker || !dockerAvailable) {
        console.log('Skipping: Docker not available');
        return;
      }

      const sandbox = await DockerSandboxManager.create({
        timeout: 120000,
        runtime: 'node24',
      });

      try {
        // Create a minimal package.json
        await sandbox.writeFiles({
          'package.json': JSON.stringify({
            name: 'test-project',
            version: '1.0.0',
            type: 'module',
          }),
        });

        // Run npm install (should succeed even with no deps)
        const result = await sandbox.runCommand('npm', ['install']);
        expect(result.exitCode).toBe(0);

        // Check node version
        const nodeResult = await sandbox.runCommand('node', ['--version']);
        expect(nodeResult.exitCode).toBe(0);
        expect(nodeResult.stdout).toMatch(/^v2[04]/); // v20 or v24
      } finally {
        await sandbox.stop();
      }
    }, 180000); // 3 minute timeout

    it('returns correct exit codes for failed commands', async () => {
      if (skipDocker || !dockerAvailable) {
        console.log('Skipping: Docker not available');
        return;
      }

      const sandbox = await DockerSandboxManager.create({
        timeout: 60000,
        runtime: 'node24',
      });

      try {
        const result = await sandbox.runCommand('false'); // Always exits with 1
        expect(result.exitCode).toBe(1);
      } finally {
        await sandbox.stop();
      }
    }, 120000);

    it('can run shell commands', async () => {
      if (skipDocker || !dockerAvailable) {
        console.log('Skipping: Docker not available');
        return;
      }

      const sandbox = await DockerSandboxManager.create({
        timeout: 60000,
        runtime: 'node24',
      });

      try {
        const result = await sandbox.runShell('echo "hello" && echo "world"');
        expect(result.exitCode).toBe(0);
        expect(result.stdout).toContain('hello');
        expect(result.stdout).toContain('world');
      } finally {
        await sandbox.stop();
      }
    }, 120000);

    // Regression: Docker multiplexes stdout/stderr into a single framed stream,
    // and large output is delivered across many `data` events that split frames
    // at arbitrary byte offsets. The previous parser read each chunk
    // independently and mis-read bytes that straddled a chunk boundary, silently
    // dropping/corrupting output (e.g. truncating large file reads via `cat`).
    // A large file round-trip reproduces the corruption on main without the fix.
    it('reads back a large file without dropping or corrupting bytes', async () => {
      if (skipDocker || !dockerAvailable) {
        console.log('Skipping: Docker not available');
        return;
      }

      const sandbox = await DockerSandboxManager.create({
        timeout: 60000,
        runtime: 'node24',
      });

      try {
        // ~512KB of line-numbered content. Numbered lines make any dropped or
        // reordered bytes detectable, and the size guarantees the output spans
        // many stream chunks/frames.
        const lines: string[] = [];
        for (let i = 0; i < 8192; i++) {
          lines.push(`line ${i.toString().padStart(6, '0')}: café[0m✓ ${'x'.repeat(48)}`);
        }
        const content = lines.join('\n') + '\n';

        await sandbox.writeFiles({ 'large.txt': content });

        const readBack = await sandbox.readFile('large.txt');
        expect(readBack.length).toBe(content.length);
        expect(readBack).toBe(content);
      } finally {
        await sandbox.stop();
      }
    }, 120000);
  });

  // These need no daemon: only `runCommand` is stubbed, so the real
  // `readFileBuffer` implementation runs against a fake transport.
  describe('readFileBuffer', () => {
    function stubbedSandbox(
      run: (command: string, args: string[]) => CommandResult
    ): DockerSandboxManager {
      const sandbox = Object.create(
        DockerSandboxManager.prototype
      ) as DockerSandboxManager;
      sandbox.runCommand = async (command: string, args: string[] = []) =>
        run(command, args);
      return sandbox;
    }

    it('round-trips binary content that readFile would corrupt', async () => {
      const calls: Array<[string, string[]]> = [];
      const sandbox = stubbedSandbox((command, args) => {
        calls.push([command, args]);
        return { stdout: PNG_BYTES.toString('base64'), stderr: '', exitCode: 0 };
      });

      const content = await sandbox.readFileBuffer('public/favicon.png');

      expect(calls).toEqual([['base64', ['public/favicon.png']]]);
      expect(Buffer.compare(content, PNG_BYTES)).toBe(0);
    });

    it('throws when the file cannot be read', async () => {
      const sandbox = stubbedSandbox(() => ({
        stdout: '',
        stderr: 'base64: missing.png: No such file or directory',
        exitCode: 1,
      }));

      await expect(sandbox.readFileBuffer('missing.png')).rejects.toThrow(
        'Failed to read file missing.png: base64: missing.png: No such file or directory'
      );
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

const { createVercelSandbox } = vi.hoisted(() => ({
  createVercelSandbox: vi.fn(),
}));

vi.mock('@vercel/sandbox', () => ({
  Sandbox: { create: createVercelSandbox },
}));

import { DEFAULT_SANDBOX_TIMEOUT, SandboxManager, SandboxSessionRecycledError, createSandbox } from './sandbox.js';

/**
 * Minimal stand-in for the SDK's Sandbox at the wrapper's external boundary.
 * `sessionId` is mutable so a test can simulate the SDK swapping in a fresh
 * session behind the wrapper's back.
 */
function fakeSandbox(name = 'sandbox-123') {
  const state = { sessionId: 'session-1' };
  const finished = {
    exitCode: 0,
    stdout: async () => 'ok\n',
    stderr: async () => '',
  };
  return {
    state,
    name,
    image: undefined as string | undefined,
    currentSession: () => ({ sessionId: state.sessionId }),
    runCommand: vi.fn(async () => ({ wait: async () => finished })),
    writeFiles: vi.fn(async () => {}),
    stop: vi.fn(async () => {}),
    createUser: vi.fn(async (username: string) => fakeUser(username)),
  };
}

/**
 * Stand-in for the SDK's SandboxUser. The first command it receives is the
 * wrapper's own setup step, which reports the user's PATH on stdout.
 */
function fakeUser(username: string, path = '/usr/local/bin:/usr/bin:/bin') {
  const commands: Array<Record<string, unknown>> = [];
  const finished = (stdout: string) => ({ exitCode: 0, stdout: async () => stdout, stderr: async () => '' });
  return {
    username,
    homeDir: `/home/${username}`,
    commands,
    runCommand: vi.fn(async (params: Record<string, unknown>) => {
      commands.push(params);
      return { wait: async () => finished(commands.length === 1 ? path : 'as-user\n') };
    }),
    writeFiles: vi.fn(async () => {}),
  };
}

describe('SandboxManager.create', () => {
  beforeEach(() => {
    createVercelSandbox.mockReset();
    createVercelSandbox.mockResolvedValue(fakeSandbox());
    // The test setup loads .env for every file; a developer with the token-auth
    // triple configured would otherwise see credentials spread into the create
    // call and the exact default-path assertion below fail locally only.
    vi.stubEnv('VERCEL_TOKEN', '');
    vi.stubEnv('VERCEL_TEAM_ID', '');
    vi.stubEnv('VERCEL_PROJECT_ID', '');
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it('preserves the existing node24 runtime and ephemeral lifecycle by default', async () => {
    const sandbox = await SandboxManager.create();

    expect(createVercelSandbox).toHaveBeenCalledWith({
      runtime: 'node24',
      timeout: DEFAULT_SANDBOX_TIMEOUT,
      persistent: false,
      onResume: expect.any(Function),
    });
    expect(sandbox.sandboxId).toBe('sandbox-123');
  });

  it('preserves explicit runtime, timeout, and credential options', async () => {
    const sandbox = await SandboxManager.create({
      runtime: 'node20',
      timeout: 30_000,
      token: 'token',
      teamId: 'team-id',
      projectId: 'project-id',
    });

    expect(createVercelSandbox).toHaveBeenCalledWith({
      runtime: 'node20',
      timeout: 30_000,
      persistent: false,
      onResume: expect.any(Function),
      token: 'token',
      teamId: 'team-id',
      projectId: 'project-id',
    });
    expect(sandbox.sandboxId).toBe('sandbox-123');
  });

  it('rejects an SDK-initiated resume and stops the replacement session so nothing idles until timeout', async () => {
    await SandboxManager.create();
    const { onResume } = createVercelSandbox.mock.calls[0][0] as {
      onResume: (sandbox: { name: string; stop: () => Promise<unknown> }) => Promise<void>;
    };
    const replacement = { name: 'sandbox-123', stop: vi.fn(async () => ({})) };

    await expect(onResume(replacement)).rejects.toBeInstanceOf(SandboxSessionRecycledError);
    expect(replacement.stop).toHaveBeenCalledTimes(1);
  });

  it('still fails the run when the replacement session cannot be stopped', async () => {
    await SandboxManager.create();
    const { onResume } = createVercelSandbox.mock.calls[0][0] as {
      onResume: (sandbox: { name: string; stop: () => Promise<unknown> }) => Promise<void>;
    };
    const replacement = {
      name: 'sandbox-123',
      stop: vi.fn(async () => {
        throw new Error('already stopping');
      }),
    };

    await expect(onResume(replacement)).rejects.toBeInstanceOf(SandboxSessionRecycledError);
  });

  it('fails the next operation when the SDK swapped sessions without reporting a resume', async () => {
    const fake = fakeSandbox();
    createVercelSandbox.mockResolvedValue(fake);
    const sandbox = await SandboxManager.create();

    expect((await sandbox.runCommand('echo', ['ok'])).stdout).toBe('ok\n');

    fake.state.sessionId = 'session-2';

    await expect(sandbox.runCommand('echo', ['ok'])).rejects.toBeInstanceOf(SandboxSessionRecycledError);
    await expect(sandbox.runShell('true')).rejects.toBeInstanceOf(SandboxSessionRecycledError);
    await expect(sandbox.writeFiles({ 'a.txt': 'a' })).rejects.toBeInstanceOf(SandboxSessionRecycledError);
    await expect(sandbox.uploadFiles([{ path: 'b.txt', content: 'b' }])).rejects.toBeInstanceOf(
      SandboxSessionRecycledError
    );
  });
});

describe('SandboxManager.create opt-in image and user', () => {
  beforeEach(() => {
    createVercelSandbox.mockReset();
    createVercelSandbox.mockResolvedValue(fakeSandbox());
    vi.stubEnv('VERCEL_TOKEN', '');
    vi.stubEnv('VERCEL_TEAM_ID', '');
    vi.stubEnv('VERCEL_PROJECT_ID', '');
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it('boots from an image instead of the legacy runtime when image is set', async () => {
    const fake = fakeSandbox();
    fake.image = 'vercel/sandbox/node@sha256:abc';
    createVercelSandbox.mockResolvedValue(fake);

    const sandbox = await SandboxManager.create({ image: 'vercel/sandbox/node:24' });

    const request = createVercelSandbox.mock.calls[0][0] as Record<string, unknown>;
    expect(request.image).toBe('vercel/sandbox/node:24');
    expect(request).not.toHaveProperty('runtime');
    expect(sandbox.image).toBe('vercel/sandbox/node@sha256:abc');
    // Images do not ship the legacy `/vercel/sandbox`; the wrapper creates it
    // from `/` so later commands have a valid cwd.
    expect(fake.runCommand).toHaveBeenCalledWith({ cmd: 'mkdir', args: ['-p', '/vercel/sandbox'], cwd: '/', detached: true });
  });

  it('stops the sandbox and fails create when the image working directory cannot be created', async () => {
    const fake = fakeSandbox();
    fake.runCommand.mockResolvedValue({
      wait: async () => ({ exitCode: 1, stdout: async () => '', stderr: async () => 'mkdir: read-only file system' }),
    });
    createVercelSandbox.mockResolvedValue(fake);

    await expect(SandboxManager.create({ image: 'vercel/sandbox/node:24' })).rejects.toThrow(/read-only file system/);
    expect(fake.stop).toHaveBeenCalledTimes(1);
  });

  it('refuses image together with runtime before contacting the SDK', async () => {
    await expect(SandboxManager.create({ image: 'vercel/sandbox/node:24', runtime: 'node24' })).rejects.toThrow(
      /mutually exclusive/
    );
    expect(createVercelSandbox).not.toHaveBeenCalled();
  });

  it('runs commands and file writes as the created user from a user-owned workspace with a writable npm prefix', async () => {
    const fake = fakeSandbox();
    createVercelSandbox.mockResolvedValue(fake);

    const sandbox = await SandboxManager.create({ user: 'user' });
    const user = await fake.createUser.mock.results[0].value;

    expect(fake.createUser).toHaveBeenCalledWith('user');
    expect(sandbox.getWorkingDirectory()).toBe('/home/user/workspace');
    // Setup ran as the user and prepared the workspace + npm prefix.
    expect(user.commands[0]).toMatchObject({ cmd: 'bash' });
    expect(String((user.commands[0].args as string[])[1])).toContain('mkdir -p "/home/user/workspace" "/home/user/.npm-global/bin"');
    expect(String((user.commands[0].args as string[])[1])).toContain("prefix=%s");

    const result = await sandbox.runShell('whoami', { FOO: 'bar' });

    expect(result.stdout).toBe('as-user\n');
    // Routed through the user, not the sandbox's default account.
    expect(fake.runCommand).not.toHaveBeenCalled();
    expect(user.commands[1]).toMatchObject({ cwd: '/home/user/workspace' });

    await sandbox.writeFiles({ 'src/index.ts': 'export {};' });
    expect(user.writeFiles).toHaveBeenCalledWith([
      { path: '/home/user/workspace/src/index.ts', content: Buffer.from('export {};', 'utf-8') },
    ]);
    expect(fake.writeFiles).not.toHaveBeenCalled();
  });

  it('keeps env values out of argv in user mode: they are sourced from a user-owned file', async () => {
    const fake = fakeSandbox();
    createVercelSandbox.mockResolvedValue(fake);
    const sandbox = await SandboxManager.create({ user: 'user' });
    const user = await fake.createUser.mock.results[0].value;

    await sandbox.runCommand('node', ['run.mjs'], { env: { ANTHROPIC_AUTH_TOKEN: "sk-it's-secret", FOO: 'bar' } });

    const params = user.commands[1];
    expect(params.env).toBeUndefined();
    expect(JSON.stringify(params.args)).not.toContain('secret');
    const [flag, bootstrap, argv0, envFile, ...rest] = params.args as string[];
    expect(flag).toBe('-c');
    expect(bootstrap).toBe('set -a && . "$1" && set +a && shift && exec "$@"');
    expect(argv0).toBe('bash');
    expect(envFile).toMatch(/^\/home\/user\/\.agent-eval\/env-[0-9a-f]{16}\.sh$/);
    expect(rest).toEqual(['node', 'run.mjs']);

    const [write] = user.writeFiles.mock.calls.at(-1)!;
    expect(write[0].path).toBe(envFile);
    expect(write[0].content.toString('utf-8')).toBe(
      [
        "ANTHROPIC_AUTH_TOKEN='sk-it'\\''s-secret'",
        "FOO='bar'",
        "PATH='/home/user/.npm-global/bin:/usr/local/bin:/usr/bin:/bin'",
        "SUDO_COMMAND=''",
        "SUDO_GID=''",
        "SUDO_UID=''",
        "SUDO_USER=''",
        '',
      ].join('\n')
    );
  });

  it('writes each distinct env set once and reuses the file for repeated commands', async () => {
    const fake = fakeSandbox();
    createVercelSandbox.mockResolvedValue(fake);
    const sandbox = await SandboxManager.create({ user: 'user' });
    const user = await fake.createUser.mock.results[0].value;

    await sandbox.runCommand('echo', ['a'], { env: { FOO: 'bar' } });
    await sandbox.runShell('echo b', { FOO: 'bar' });
    await sandbox.runCommand('echo', ['c']);

    const envFiles = user.writeFiles.mock.calls.map(([files]: [Array<{ path: string }>]) => files[0].path);
    expect(new Set(envFiles).size).toBe(2);
    const argvFile = (i: number) => (user.commands[i].args as string[])[3];
    expect(argvFile(1)).toBe(argvFile(2));
    expect(argvFile(3)).not.toBe(argvFile(1));
  });

  it('rejects env names that could break out of the sourced file', async () => {
    const fake = fakeSandbox();
    createVercelSandbox.mockResolvedValue(fake);
    const sandbox = await SandboxManager.create({ user: 'user' });

    await expect(sandbox.runCommand('echo', [], { env: { 'BAD NAME; rm -rf /': 'x' } })).rejects.toThrow(
      /Invalid environment variable name/
    );
  });

  it('lets a caller override PATH for one command without losing the user identity env', async () => {
    const fake = fakeSandbox();
    createVercelSandbox.mockResolvedValue(fake);
    const sandbox = await SandboxManager.create({ user: 'user' });
    const user = await fake.createUser.mock.results[0].value;

    await sandbox.runCommand('node', ['-v'], { env: { PATH: '/custom/bin' } });

    const [write] = user.writeFiles.mock.calls.at(-1)!;
    const content = write[0].content.toString('utf-8');
    expect(content).toContain("PATH='/custom/bin'");
    expect(content).toContain("SUDO_USER=''");
  });

  it('stops the sandbox and fails create when the user cannot be prepared', async () => {
    const fake = fakeSandbox();
    fake.createUser.mockRejectedValue(new Error('useradd: permission denied'));
    createVercelSandbox.mockResolvedValue(fake);

    await expect(SandboxManager.create({ user: 'user' })).rejects.toThrow('useradd: permission denied');
    expect(fake.stop).toHaveBeenCalledTimes(1);
  });

  it('leaves the default account and env untouched when user is not set', async () => {
    const fake = fakeSandbox();
    createVercelSandbox.mockResolvedValue(fake);
    const sandbox = await SandboxManager.create();

    await sandbox.runCommand('echo', ['ok'], { env: { FOO: 'bar' } });

    expect(fake.createUser).not.toHaveBeenCalled();
    expect(fake.runCommand).toHaveBeenCalledWith({
      cmd: 'echo',
      args: ['ok'],
      env: { FOO: 'bar' },
      cwd: '/vercel/sandbox',
      detached: true,
    });
  });
});

