import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdirSync, rmSync, existsSync, readFileSync, writeFileSync } from 'fs';
import { join, resolve, dirname } from 'path';
import { execSync } from 'child_process';
import { fileURLToPath } from 'url';
import { initProject, getPostInitInstructions } from './init.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const PROJECT_ROOT = resolve(__dirname, '../..');

const TEST_DIR = '/tmp/eval-framework-init-test';

describe('init utilities', () => {
  beforeEach(() => {
    mkdirSync(TEST_DIR, { recursive: true });
  });

  afterEach(() => {
    if (existsSync(TEST_DIR)) {
      rmSync(TEST_DIR, { recursive: true });
    }
  });

  describe('initProject', () => {
    it('creates project directory structure', () => {
      const projectDir = initProject({
        name: 'my-evals',
        targetDir: TEST_DIR,
      });

      expect(existsSync(projectDir)).toBe(true);
      expect(existsSync(join(projectDir, 'package.json'))).toBe(true);
      expect(existsSync(join(projectDir, '.env.example'))).toBe(true);
      expect(existsSync(join(projectDir, '.gitignore'))).toBe(true);
      expect(existsSync(join(projectDir, 'experiments'))).toBe(true);
      expect(existsSync(join(projectDir, 'evals'))).toBe(true);
    });

    it('creates Claude Code experiment config', () => {
      const projectDir = initProject({
        name: 'test-project',
        targetDir: TEST_DIR,
      });

      const configPath = join(projectDir, 'experiments/cc.ts');
      expect(existsSync(configPath)).toBe(true);

      const content = readFileSync(configPath, 'utf-8');
      expect(content).toContain("agent: 'vercel-ai-gateway/claude-code'");
    });

    it('creates example eval fixture', () => {
      const projectDir = initProject({
        name: 'test-project',
        targetDir: TEST_DIR,
      });

      const evalDir = join(projectDir, 'evals/add-greeting');
      expect(existsSync(evalDir)).toBe(true);
      expect(existsSync(join(evalDir, 'PROMPT.md'))).toBe(true);
      expect(existsSync(join(evalDir, 'EVAL.ts'))).toBe(true);
      expect(existsSync(join(evalDir, 'package.json'))).toBe(true);
      expect(existsSync(join(evalDir, 'src/App.tsx'))).toBe(true);
    });

    it('creates valid package.json with correct name', () => {
      const projectDir = initProject({
        name: 'custom-name',
        targetDir: TEST_DIR,
      });

      const pkgPath = join(projectDir, 'package.json');
      const pkg = JSON.parse(readFileSync(pkgPath, 'utf-8'));

      expect(pkg.name).toBe('custom-name');
      expect(pkg.type).toBe('module');
      expect(pkg.scripts).toBeUndefined();
    });

    it('creates eval fixture with type: module', () => {
      const projectDir = initProject({
        name: 'test-project',
        targetDir: TEST_DIR,
      });

      const evalPkgPath = join(projectDir, 'evals/add-greeting/package.json');
      const pkg = JSON.parse(readFileSync(evalPkgPath, 'utf-8'));

      expect(pkg.type).toBe('module');
    });

    it('throws if directory already exists', () => {
      // Create the directory first
      mkdirSync(join(TEST_DIR, 'existing-project'));

      expect(() =>
        initProject({
          name: 'existing-project',
          targetDir: TEST_DIR,
        })
      ).toThrow('Directory already exists');
    });

    it('creates .env.example with required variables', () => {
      const projectDir = initProject({
        name: 'test-project',
        targetDir: TEST_DIR,
      });

      const envPath = join(projectDir, '.env.example');
      const content = readFileSync(envPath, 'utf-8');

      expect(content).toContain('AI_GATEWAY_API_KEY');
      expect(content).toContain('VERCEL_TOKEN');
    });

    it('creates .gitignore with common patterns', () => {
      const projectDir = initProject({
        name: 'test-project',
        targetDir: TEST_DIR,
      });

      const gitignorePath = join(projectDir, '.gitignore');
      const content = readFileSync(gitignorePath, 'utf-8');

      expect(content).toContain('node_modules');
      expect(content).toContain('.env');
      expect(content).toContain('results/');
    });

    it('passes TypeScript type checking after npm install', { timeout: 120000 }, () => {
      const projectDir = initProject({
        name: 'typecheck-test',
        targetDir: TEST_DIR,
      });

      // For testing, link the local package instead of downloading from npm
      // This allows the test to work before publishing
      const pkgPath = join(projectDir, 'package.json');
      const pkg = JSON.parse(readFileSync(pkgPath, 'utf-8'));
      pkg.devDependencies['@vercel/agent-eval'] = `file:${PROJECT_ROOT}`;
      writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));

      // Install dependencies
      execSync('npm install', {
        cwd: projectDir,
        stdio: 'pipe',
      });

      // Run type checker - this should pass without errors
      // This catches issues like missing @types/node, vitest types, etc.
      execSync('npx tsc --noEmit', {
        cwd: projectDir,
        stdio: 'pipe',
      });
    });
  });

  describe('getPostInitInstructions', () => {
    it('returns instructions with project path', () => {
      const instructions = getPostInitInstructions('/path/to/project', 'my-project');

      expect(instructions).toContain('/path/to/project');
      expect(instructions).toContain('cd my-project');
      expect(instructions).toContain('npm install');
    });
  });
});

import { describe, it, expect } from 'vitest';
import {
  validateConfig,
  resolveConfig,
  resolveEvalNames,
  CONFIG_DEFAULTS,
} from './config.js';
import { registerAgent } from './agents/index.js';
import type { Agent } from './agents/types.js';
import type { AgentDefinition } from './agents/plugin/contract.js';

describe('validateConfig', () => {
  it('accepts valid minimal config', () => {
    const config = { agent: 'claude-code' };
    expect(() => validateConfig(config)).not.toThrow();
  });

  it('accepts valid full config', () => {
    const config = {
      agent: 'claude-code',
      model: 'opus',
      evals: ['eval-1', 'eval-2'],
      runs: 5,
      earlyExit: false,
      scripts: ['build', 'lint'],
      validation: 'none',
      timeout: 600,
      brands: [
        {
          id: 'vercel',
          name: 'Vercel',
          domain: 'vercel.com',
          aliases: ['Vercel Platform'],
          isYourBrand: true,
        },
      ],
    };
    expect(() => validateConfig(config)).not.toThrow();
  });

  it('accepts array of models', () => {
    const config = {
      agent: 'claude-code',
      model: ['opus', 'sonnet', 'haiku'],
    };
    expect(() => validateConfig(config)).not.toThrow();
  });

  it('accepts function evals filter', () => {
    const config = {
      agent: 'claude-code',
      evals: (name: string) => name.startsWith('auth-'),
    };
    expect(() => validateConfig(config)).not.toThrow();
  });

  it('accepts a custom agent identifier for registry resolution', () => {
    const config = { agent: 'my-custom-agent' };
    expect(validateConfig(config).agent).toBe('my-custom-agent');
  });

  it('rejects an empty agent identifier', () => {
    const config = { agent: '' };
    expect(() => validateConfig(config)).toThrow('Invalid experiment configuration');
  });

  it('rejects non-positive runs', () => {
    const config = { agent: 'claude-code', runs: 0 };
    expect(() => validateConfig(config)).toThrow('Invalid experiment configuration');
  });

  it('keeps webResearch through validation (zod strips unknown keys)', () => {
    const config = { agent: 'claude-code', webResearch: true };
    expect(validateConfig(config).webResearch).toBe(true);
  });

  it('rejects non-boolean webResearch', () => {
    const config = { agent: 'claude-code', webResearch: 'yes' };
    expect(() => validateConfig(config)).toThrow('Invalid experiment configuration');
  });

  it('keeps disableBundledSkills through validation', () => {
    const config = { agent: 'claude-code', disableBundledSkills: true };
    expect(validateConfig(config).disableBundledSkills).toBe(true);
  });

  it('rejects non-boolean disableBundledSkills', () => {
    const config = { agent: 'claude-code', disableBundledSkills: 'yes' };
    expect(() => validateConfig(config)).toThrow('Invalid experiment configuration');
  });

  it('keeps sandboxImage and sandboxUser through validation and resolution', () => {
    const config = { agent: 'claude-code', sandboxImage: 'vercel/sandbox/node:24', sandboxUser: 'user' };
    const validated = validateConfig(config);
    expect(validated.sandboxImage).toBe('vercel/sandbox/node:24');
    expect(validated.sandboxUser).toBe('user');
    const resolved = resolveConfig(validated);
    expect(resolved.sandboxImage).toBe('vercel/sandbox/node:24');
    expect(resolved.sandboxUser).toBe('user');
  });

  it('leaves sandboxImage and sandboxUser undefined by default', () => {
    const resolved = resolveConfig(validateConfig({ agent: 'claude-code' }));
    expect(resolved.sandboxImage).toBeUndefined();
    expect(resolved.sandboxUser).toBeUndefined();
  });

  it('rejects a sandboxUser the sandbox SDK would refuse', () => {
    expect(() => validateConfig({ agent: 'claude-code', sandboxUser: 'Agent One' })).toThrow(
      'Invalid experiment configuration'
    );
    expect(() => validateConfig({ agent: 'claude-code', sandboxUser: '1user' })).toThrow(
      'Invalid experiment configuration'
    );
  });

  it('accepts a pinned judge (model only, agent defaults to codegen)', () => {
    const config = { agent: 'claude-code', judge: { model: 'claude-opus-4-8' } };
    expect(validateConfig(config).judge).toEqual({ model: 'claude-opus-4-8' });
  });

  it('accepts a pinned judge with an explicit agent', () => {
    const config = {
      agent: 'codex',
      judge: { agent: 'vercel-ai-gateway/claude-code', model: 'claude-opus-4-8' },
    };
    expect(validateConfig(config).judge).toEqual({
      agent: 'vercel-ai-gateway/claude-code',
      model: 'claude-opus-4-8',
    });
  });

  it('accepts the PI agent, as codegen agent and as pinned judge', () => {
    const agent = 'vercel-ai-gateway/pi-coding-agent';
    const config = validateConfig({
      agent,
      agentOptions: { thinking: 'high' },
      judge: { agent, model: 'anthropic/claude-sonnet-4.5' },
    });
    expect(config.agent).toBe(agent);
    expect(config.judge?.agent).toBe(agent);
    expect(resolveConfig(config).agentOptions).toEqual({ thinking: 'high' });
  });

  it('rejects a judge without a model (pinning the model is required)', () => {
    const config = { agent: 'claude-code', judge: { agent: 'claude-code' } };
    expect(() => validateConfig(config)).toThrow('Invalid experiment configuration');
  });

  it('passes reporters through validation and resolution untouched', () => {
    class CountingReporter {
      name = 'counter';
      #count = 0;
      onRunComplete() {
        this.#count++;
      }
      get count() {
        return this.#count;
      }
    }
    const reporter = new CountingReporter();

    const resolved = resolveConfig(validateConfig({ agent: 'claude-code', reporters: [reporter] }));
    resolved.reporters![0].onRunComplete!({} as never);

    // The same instance comes back, so state kept on `this` keeps working.
    expect(resolved.reporters![0]).toBe(reporter);
    expect(reporter.count).toBe(1);
  });

  it('leaves reporters undefined by default', () => {
    expect(resolveConfig(validateConfig({ agent: 'claude-code' })).reporters).toBeUndefined();
  });

  it('rejects a reporter without a name', () => {
    expect(() => validateConfig({ agent: 'claude-code', reporters: [{ onRunComplete: () => {} }] })).toThrow(
      'reporters.0: must be an object with a non-empty name'
    );
  });

  it('keeps agentEnv through validation and resolution', () => {
    const agentEnv = { DEPLOY_TOKEN: '[REDACTED]', NPM_CONFIG_REGISTRY: 'https://npm.example.com' };

    expect(resolveConfig(validateConfig({ agent: 'claude-code', agentEnv })).agentEnv).toEqual(agentEnv);
    expect(resolveConfig(validateConfig({ agent: 'claude-code' })).agentEnv).toBeUndefined();
  });

  it('rejects agentEnv names a shell cannot hold and non-string values', () => {
    expect(() => validateConfig({ agent: 'claude-code', agentEnv: { 'DEPLOY-TOKEN': 'x' } })).toThrow(
      'must be a valid environment variable name'
    );
    expect(() => validateConfig({ agent: 'claude-code', agentEnv: { PORT: 3000 } })).toThrow('agentEnv.PORT');
  });

  it('keeps verifier and protectedPaths through validation and resolution', () => {
    const resolved = resolveConfig(
      validateConfig({ agent: 'claude-code', verifier: 'separate', protectedPaths: ['fixtures/**'] })
    );

    expect(resolved.verifier).toBe('separate');
    expect(resolved.protectedPaths).toEqual(['fixtures/**']);
    const defaults = resolveConfig(validateConfig({ agent: 'claude-code' }));
    expect(defaults.verifier).toBeUndefined();
    expect(defaults.protectedPaths).toBeUndefined();
  });

  it('rejects an unknown verifier mode and empty protected paths', () => {
    expect(() => validateConfig({ agent: 'claude-code', verifier: 'isolated' })).toThrow('verifier');
    expect(() => validateConfig({ agent: 'claude-code', protectedPaths: [''] })).toThrow('protectedPaths.0');
  });

  it('rejects a judge with an invalid agent', () => {
    const config = { agent: 'claude-code', judge: { agent: 'nope', model: 'x' } };
    expect(() => validateConfig(config)).toThrow('Invalid experiment configuration');
  });
});

describe('resolveConfig', () => {
  it('applies defaults for minimal config', () => {
    const config = { agent: 'claude-code' as const };
    const resolved = resolveConfig(config);

    expect(resolved.agent).toBe('claude-code');
    expect(resolved.model).toBe('native-default');
    expect(resolved.runs).toBe(CONFIG_DEFAULTS.runs);
    expect(resolved.earlyExit).toBe(CONFIG_DEFAULTS.earlyExit);
    expect(resolved.validation).toBe(CONFIG_DEFAULTS.validation);
    expect(resolved.evals).toBe('*');
    expect(resolved.modelPolicy).toBe('native-default');
  });

  it('preserves provided values', () => {
    const config = {
      agent: 'claude-code' as const,
      model: 'haiku' as const,
      runs: 10,
      earlyExit: false,
    };
    const resolved = resolveConfig(config);

    expect(resolved.model).toBe('haiku');
    expect(resolved.modelPolicy).toBe('agent-default');
    expect(resolved.runs).toBe(10);
    expect(resolved.earlyExit).toBe(false);
  });

  it('resolves an agent registered by an experiment module', () => {
    const definition: AgentDefinition = {
      name: 'config-test-custom-agent',
      displayName: 'Config Test Custom Agent',
      defaultModel: 'custom-default',
      o11yAgentName: 'claude-code',
      runnerPath: '/custom/run.mjs',
      getApiKeyEnvVar: () => 'CUSTOM_AGENT_API_KEY',
      install: () => [],
      configFiles: () => [],
      authEnv: () => ({}),
    };
    const customAgent: Agent = {
      name: definition.name,
      displayName: definition.displayName,
      getApiKeyEnvVar: definition.getApiKeyEnvVar,
      getDefaultModel: () => definition.defaultModel,
      run: async () => ({ success: true, output: '', duration: 0 }),
      definition,
    };
    registerAgent(customAgent);

    expect(resolveConfig({ agent: customAgent.name }).agent).toBe(customAgent.name);
  });

  it('rejects an unregistered custom agent during resolution', () => {
    expect(() => resolveConfig({ agent: 'unregistered-config-test-agent' })).toThrow(
      'Unknown agent: unregistered-config-test-agent'
    );
  });

  it('passes webResearch through and leaves it undefined by default', () => {
    expect(resolveConfig({ agent: 'claude-code' as const }).webResearch).toBeUndefined();
    expect(resolveConfig({ agent: 'claude-code' as const, webResearch: true }).webResearch).toBe(true);
  });

  it('passes disableBundledSkills through and leaves it undefined by default', () => {
    expect(resolveConfig({ agent: 'claude-code' as const }).disableBundledSkills).toBeUndefined();
    expect(
      resolveConfig({ agent: 'claude-code' as const, disableBundledSkills: true })
        .disableBundledSkills
    ).toBe(true);
  });

  it('accepts agents with no bundled skills and rejects unsupported agents', () => {
    expect(
      resolveConfig({ agent: 'vercel-ai-gateway/opencode', disableBundledSkills: true })
        .disableBundledSkills
    ).toBe(true);
    expect(() =>
      resolveConfig({ agent: 'gemini', disableBundledSkills: true })
    ).toThrow('Agent gemini does not support disableBundledSkills');
    expect(() =>
      resolveConfig({
        agent: 'vercel-ai-gateway/claude-code',
        disableBundledSkills: true,
        judge: { agent: 'gemini', model: 'gemini-2.5-pro' },
      })
    ).toThrow('Agent gemini does not support disableBundledSkills');
  });

  it('requires research mode for fx', () => {
    expect(() => resolveConfig({ agent: 'vercel-ai-gateway/fx' })).toThrow(
      'Agent vercel-ai-gateway/fx requires webResearch: true'
    );
    expect(
      resolveConfig({
        agent: 'vercel-ai-gateway/fx',
        webResearch: true,
        disableBundledSkills: true,
      }).agent
    ).toBe('vercel-ai-gateway/fx');
  });

  it('does not allow fx as a cross-agent judge', () => {
    const config = validateConfig({
      agent: 'vercel-ai-gateway/claude-code',
      judge: { agent: 'vercel-ai-gateway/fx', model: 'openai/gpt-5.6-sol' },
      webResearch: true,
    });
    expect(() => resolveConfig(config)).toThrow(
      'Agent vercel-ai-gateway/fx does not support cross-agent judging'
    );
  });

  it('passes judge through and leaves it undefined by default', () => {
    expect(resolveConfig({ agent: 'claude-code' as const }).judge).toBeUndefined();
    expect(
      resolveConfig({ agent: 'claude-code' as const, judge: { model: 'claude-opus-4-8' } }).judge
    ).toEqual({ model: 'claude-opus-4-8' });
  });

});

describe('resolveEvalNames', () => {
  const availableEvals = ['auth-login', 'auth-logout', 'ui-button', 'api-endpoint'];

  it('returns all evals for "*" filter', () => {
    const result = resolveEvalNames('*', availableEvals);
    expect(result).toEqual(availableEvals);
  });

  it('returns single eval for string filter', () => {
    const result = resolveEvalNames('auth-login', availableEvals);
    expect(result).toEqual(['auth-login']);
  });

  it('filters evals with function', () => {
    const result = resolveEvalNames((name) => name.startsWith('auth-'), availableEvals);
    expect(result).toEqual(['auth-login', 'auth-logout']);
  });

  it('throws for non-existent single eval', () => {
    expect(() => resolveEvalNames('non-existent', availableEvals)).toThrow(
      'Eval "non-existent" not found'
    );
  });

  it('supports glob patterns for nested directories', () => {
    const nestedEvals = [
      'vercel-cli/deploy',
      'vercel-cli/link',
      'vercel-cli/env',
      'flags/create',
      'flags/update',
      'analytics/track',
    ];

    // Match all vercel-cli evals
    expect(resolveEvalNames('vercel-cli/*', nestedEvals)).toEqual([
      'vercel-cli/deploy',
      'vercel-cli/link',
      'vercel-cli/env',
    ]);

    // Match all flags evals
    expect(resolveEvalNames('flags/*', nestedEvals)).toEqual(['flags/create', 'flags/update']);

    // Match specific nested eval
    expect(resolveEvalNames('vercel-cli/deploy', nestedEvals)).toEqual(['vercel-cli/deploy']);

    // Match all deploy evals across folders
    expect(resolveEvalNames('*/deploy', nestedEvals)).toEqual(['vercel-cli/deploy']);
  });

  it('supports glob patterns in arrays', () => {
    const nestedEvals = [
      'vercel-cli/deploy',
      'vercel-cli/link',
      'flags/create',
      'analytics/track',
    ];

    const result = resolveEvalNames(['vercel-cli/*', 'analytics/*'], nestedEvals);
    expect(result).toEqual(['vercel-cli/deploy', 'vercel-cli/link', 'analytics/track']);
  });

  it('throws when glob pattern matches nothing', () => {
    expect(() => resolveEvalNames('nonexistent/*', availableEvals)).toThrow(
      'No evals matched pattern "nonexistent/*"'
    );
  });

  it('handles special characters in eval names correctly', () => {
    // Test that dots and parentheses work correctly with glob patterns
    const specialCharsEvals = [
      'test.eval',
      'test-eval',
      'vercel-cli/deploy.test',
      'vercel-cli/deploy-test',
      'folder(1)/eval',
      'web-analytics/page-views',
    ];

    // Literal match - dot should match only dot, not any character
    expect(resolveEvalNames('test.eval', specialCharsEvals)).toEqual(['test.eval']);
    expect(resolveEvalNames('test.eval', specialCharsEvals)).not.toContain('test-eval');

    // Glob pattern with dot - should match literal dot
    expect(resolveEvalNames('vercel-cli/*.test', specialCharsEvals)).toEqual([
      'vercel-cli/deploy.test',
    ]);
    expect(resolveEvalNames('vercel-cli/*.test', specialCharsEvals)).not.toContain(
      'vercel-cli/deploy-test'
    );

    // Parentheses in eval names work with wildcards
    expect(resolveEvalNames('folder(1)/*', specialCharsEvals)).toEqual(['folder(1)/eval']);

    // Wildcard patterns work correctly
    expect(resolveEvalNames('web-analytics/*', specialCharsEvals)).toEqual(['web-analytics/page-views']);
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdirSync, writeFileSync, readFileSync, rmSync, existsSync } from 'fs';
import { join } from 'path';
import {
  discoverFixtures,
